import{_ as e,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Alcance de armas y distancia","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/reach-and-spacing.md","filePath":"es/guide/combat/reach-and-spacing.md"}'),c={name:"es/guide/combat/reach-and-spacing.md"};function r(d,a,o,s,l,m){return t(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="weapon-reach-and-spacing" tabindex="-1">Alcance de armas y distancia <a class="header-anchor" href="#weapon-reach-and-spacing" aria-label="Enlace permanente a &quot;Alcance de armas y distancia&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · Experimental: distancias · No implementado.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Un arma puede tener un <a href="/Syrolands-Public/es/guide/glossary.html#reach">alcance</a> máximo y una <a href="/Syrolands-Public/es/guide/glossary.html#effective-range">distancia preferida</a> de combate distinta.</li><li>Una lanza amenaza desde más lejos, pero pierde eficacia de cerca.</li><li>La <a href="/Syrolands-Public/es/guide/characters/skills.html">habilidad</a> no alarga un arma de forma invisible.</li></ul><p><span id="at-a-glance"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspecto</th><th>Significado</th></tr></thead><tbody><tr><td>Alcance</td><td>El punto más lejano que una acción concreta puede amenazar físicamente.</td></tr><tr><td>Distancia preferida</td><td>La distancia donde mejor se maneja la acción; estar a alcance no implica estar en la distancia óptima.</td></tr><tr><td>Área cubierta</td><td>Una estocada, barrido o arco cubre una forma distinta, sin garantizar impactos adicionales.</td></tr><tr><td>Posición</td><td>La orientación, la línea de visión y el movimiento del objetivo siguen importando. Lunge extiende el golpe sin desplazarte automáticamente hacia delante.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Syrolands</th></tr></thead><tbody><tr><td>Los ataques cuerpo a cuerpo y a distancia ya dependen de la separación</td><td>Dar a las acciones cuerpo a cuerpo alcances, distancias preferidas y formas distintas.</td></tr><tr><td>Acercarse a un rival a distancia cambia el combate</td><td>Acercarse más de lo que conviene a un arma larga también se convierte en una decisión táctica.</td></tr></tbody></table><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Acércate más de lo que resulta cómodo para la lanza rival para dificultar su <a href="/Syrolands-Public/es/guide/glossary.html#handling">manejo</a>, o aléjate mientras su portador se compromete con Lunge. Ambas opciones requieren elegir bien el momento.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/weapons-and-damage.html">Armas</a> · <a href="/Syrolands-Public/es/guide/combat/special-attacks.html">Special Attacks</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/reach-and-spacing.html">Leer la especificación de diseño completa</a></p>',15)])])}const u=e(c,[["render",r]]);export{h as __pageData,u as default};
